# Step 1: Get the course_id for "International Finance"
international_finance_course_id_scalar = courses.WHERE(
    title == "International Finance"
).CALCULATE(
    target_course_id=course_id
).SINGULAR().target_course_id

# Step 2: Find the prereq_id(s) for the "International Finance" course
prerequisite_courses_info = prereqs.WHERE(
    course_id == international_finance_course_id_scalar
).CALCULATE(
    prereq_course_id_val=prereq_id
)

# Step 3: Find students who have taken any of these prerequisite courses
# Filter the 'take' records where the 'course_id' is one of the prerequisite course IDs
students_who_took_prereq_raw = take.WHERE(
    ISIN(course_id, prerequisite_courses_info.prereq_course_id_val)
)

# Step 4: Extract and return the distinct names of these students
result = students_who_took_prereq_raw.CALCULATE(
    student_full_name=student.name
).PARTITION(
    name="distinct_students", by=student_full_name
).CALCULATE(
    student_full_name
)

# Step 1: Identify station names that have been an ending point for more than 100 trips
# Partition trips by end_station_name, aggregate the count of trips per station, and filter for counts > 100.
# Using >= 101 to strictly enforce "more than 100" (i.e., 101 or more trips) as per previous feedback.
frequent_ending_stations = trips.PARTITION(name="ending_station_groups", by=end_station_name).AGGREGATE(
    trip_count=COUNT() # Count trips within each partitioned group
).WHERE(
    trip_count >= 101 # Filter for stations with 101 or more trips as an ending point
).CALCULATE(
    frequent_end_station_name=end_station_name # Select only the station names that meet the criteria for exclusion
)

# Step 2 & 3: Filter stations by city 'Palo Alto' and exclude those that are in the frequent_ending_stations list.
palo_alto_stations_not_frequent_ended_trip = stations.WHERE(
    (city == 'Palo Alto') & (~ISIN(name, frequent_ending_stations.frequent_end_station_name))
).CALCULATE(
    station_name=name # Select only the name of the stations
)

